import pandas as pd

def find_emotionally_consistent_users(user_posts: pd.DataFrame) -> pd.DataFrame:
    grouped = user_posts.groupby('user_id').agg(
        sentiment=('sentiment', 'first'),
        distinct_sentiments=('sentiment', 'nunique'),
        post_count=('post_id', 'count')
    ).reset_index()
    res = grouped[(grouped['post_count'] >= 3) & (grouped['distinct_sentiments'] == 1)]
    return res[['user_id', 'sentiment', 'post_count']].sort_values('user_id')
